  interface

    !---------------------------------------------
    ! hipblasStatusToString
    !---------------------------------------------
    !>  \brief  Auxiliary API
    !>
    !>     \details
    !>     Returns a string representing the ``hipblasStatus_t`` value.
    !>
    !>     @param[in] status - [hipblasStatus_t]
    !>             hipBLAS status to convert to string.
    function hipblasStatusToString(status) &
       result(StatusToString) &
       bind(C, name="hipblasStatusToString")
       import :: HIPBLAS_STATUS_SUCCESS, c_ptr
       integer(kind(HIPBLAS_STATUS_SUCCESS)), value :: status
       type(c_ptr) :: StatusToString
    end function hipblasStatusToString

  end interface

  !>  \brief Create the hipBLAS handle.
