      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: hipblasCreate_
      type(c_ptr) :: handle
    end function

#ifdef USE_FPOINTER_INTERFACES
    module procedure hipblasCreate_typed
#endif
  end interface

  !>  \brief Destroys the library context created using hipblasCreate().
