  !>     \brief  BLAS Level 1 API
  !>
  !>     \details
  !>     The amax functions find the first index of the element of maximum magnitude of a vector
  !>     ``x``.
  !>
  !>     - Supported precisions in rocBLAS : ``s``, ``d``, ``c``, and ``z``.
  !>     - Supported precisions in cuBLAS  : ``s``, ``d``, ``c``, and ``z``.
  !>
  !>     @param[in] handle - [hipblasHandle_t]
  !>               handle to the hipBLAS library context queue.
  !>     @param[in] n - [int]
  !>               the number of elements in x.
  !>     @param[in] x - device pointer storing vector x.
  !>     @param[in] incx - [int]
  !>               specifies the increment for the elements of y.
  !>     @param[inout] myResult
  !>               device pointer or host pointer to store the amax index.
  !>               Return value is 0.0 if n, incx<=0.
  interface hipblasIsamax
    function hipblasIsamax_(handle,n,x,incx,myResult) bind(c, name="hipblasIsamax")
      use iso_c_binding
      import
      implicit none
      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: hipblasIsamax_
      type(c_ptr),value :: handle
      integer(c_int),value :: n
      type(c_ptr),value :: x
      integer(c_int),value :: incx
      type(c_ptr),value :: myResult
    end function

#ifdef USE_FPOINTER_INTERFACES
#ifdef USE_ASSUMED_RANK_INTERFACES
    module procedure &
      hipblasIsamax_assumed_rank,&
      hipblasIsamax_assumed_rank_cptr,&
      hipblasIsamax_typed
#else
    module procedure &
      hipblasIsamax_rank_0,&
      hipblasIsamax_rank_0_cptr,&
      hipblasIsamax_rank_1,&
      hipblasIsamax_rank_1_cptr,&
      hipblasIsamax_typed
#endif
#endif
  end interface

