      use iso_c_binding
      import
      implicit none
      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: hipblasCher_
      type(c_ptr),value :: handle
      integer(kind(HIPBLAS_FILL_MODE_UPPER)),value :: uplo
      integer(c_int),value :: n
      real(c_float) :: alpha
      type(c_ptr),value :: x
      integer(c_int),value :: incx
      type(c_ptr),value :: AP
      integer(c_int),value :: lda
    end function

