    subroutine hipblasCheck(status)
      implicit none
      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: status
      if (status /= HIPBLAS_STATUS_SUCCESS) then
        write (*, *) "HIPBLAS ERROR: code = ", status
        stop 1
      end if
    end subroutine hipblasCheck

